def run(program: str) -> list[str]:
    lines = program.splitlines()
    stack = []
    output = []

    for idx, raw in enumerate(lines, start=1):
        line = raw.strip()
        if not line or line.startswith('#'):
            continue

        tokens = line.split()
        cmd = tokens[0]

        if cmd == 'PUSH':
            n = int(tokens[1])
            stack.append(n)

        elif cmd == 'POP':
            if not stack:
                raise Exception(f'Stack underflow at line {idx}')
            stack.pop()

        elif cmd == 'ADD':
            if len(stack) < 2:
                raise Exception(f'Stack underflow at line {idx}')
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)

        elif cmd == 'SUB':
            if len(stack) < 2:
                raise Exception(f'Stack underflow at line {idx}')
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)

        elif cmd == 'MUL':
            if len(stack) < 2:
                raise Exception(f'Stack underflow at line {idx}')
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)

        elif cmd == 'DIV':
            if len(stack) < 2:
                raise Exception(f'Stack underflow at line {idx}')
            b = stack.pop()
            a = stack.pop()
            if b == 0:
                raise Exception(f'Division by zero at line {idx}')
            stack.append(a // b)

        elif cmd == 'DUP':
            if not stack:
                raise Exception(f'Stack underflow at line {idx}')
            stack.append(stack[-1])

        elif cmd == 'SWAP':
            if len(stack) < 2:
                raise Exception(f'Stack underflow at line {idx}')
            a = stack.pop()
            b = stack.pop()
            stack.append(a)
            stack.append(b)

        elif cmd == 'PRINT':
            output.append(str(stack[-1]))

        else:
            raise Exception(f'Unknown command "{cmd}" at line {idx}')

    return output
